/**
 * The Squad Claude Code plugin (#2443).
 *
 * plugins/squad/ and .claude-plugin/marketplace.json are generated by scripts/build-claude-plugin.mjs
 * from the SDK (claude-plugin.ts). These tests rebuild them from source and require the committed
 * tree to match byte for byte, so the plugin can't drift from the coordinator, skills and hooks that
 * `squad init --client claude` projects. Rebuilding uses the committed plugin.json version: the
 * workspace version is bumped by every `npm run build`, and the plugin version is set at release.
 *
 * If this fails after an intended change: npm run build && node scripts/build-claude-plugin.mjs
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  buildClaudePlugin,
  buildClaudeMarketplace,
  claudePluginCoordinatorInstructions,
  CLAUDE_PLUGIN_SOURCE_DIR,
  CLAUDE_PLUGIN_STATIC_FILES,
  CLAUDE_PLUGIN_MCP_PREFIX,
  CLAUDE_HOOK_EVENTS,
} from '../packages/squad-sdk/src/client/adapters/index.js';

const ROOT = path.resolve(__dirname, '..');
const PLUGIN = path.join(ROOT, CLAUDE_PLUGIN_SOURCE_DIR);
const committedVersion: string = JSON.parse(
  fs.readFileSync(path.join(PLUGIN, '.claude-plugin', 'plugin.json'), 'utf8'),
).version;

function build() {
  return buildClaudePlugin({
    version: committedVersion,
    templateSkillsDir: path.join(ROOT, 'packages', 'squad-cli', 'templates', 'skills'),
    license: fs.readFileSync(path.join(ROOT, 'LICENSE'), 'utf8'),
  });
}

function listTree(dir: string, rel = ''): string[] {
  const out: string[] = [];
  for (const e of fs.readdirSync(path.join(dir, rel), { withFileTypes: true })) {
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory()) out.push(...listTree(dir, r));
    else out.push(r);
  }
  return out.sort();
}

const read = (rel: string) => fs.readFileSync(path.join(PLUGIN, rel), 'utf8').replace(/\r\n/g, '\n');

describe('Claude plugin: committed tree matches the SDK', () => {
  const files = build();

  it('has exactly the generated files, plus the static ones', () => {
    expect(listTree(PLUGIN)).toEqual([...files.map((f) => f.path), ...Object.keys(CLAUDE_PLUGIN_STATIC_FILES)].sort());
  });

  it('ships the icon the plugin directory wants: a square PNG of 512 to 2048 px under 2 MB, copied byte for byte', () => {
    for (const [rel, src] of Object.entries(CLAUDE_PLUGIN_STATIC_FILES)) {
      const bytes = fs.readFileSync(path.join(PLUGIN, rel));
      expect(bytes.equals(fs.readFileSync(path.join(ROOT, src))), `${rel}: run node scripts/build-claude-plugin.mjs`).toBe(true);
    }
    const icon = fs.readFileSync(path.join(PLUGIN, '.claude-plugin', 'icon.png'));
    expect(icon.subarray(0, 8).toString('hex')).toBe('89504e470d0a1a0a');
    const width = icon.readUInt32BE(16);
    const height = icon.readUInt32BE(20);
    expect(width).toBe(height);
    expect(width).toBeGreaterThanOrEqual(512);
    expect(width).toBeLessThanOrEqual(2048);
    expect(icon.length).toBeLessThan(2 * 1024 * 1024);
  });

  it('every file is byte-identical to the generated content', () => {
    const stale = files.filter((f) => read(f.path) !== f.content).map((f) => f.path);
    expect(stale, 'run: npm run build && node scripts/build-claude-plugin.mjs').toEqual([]);
  });

  // A marketplace install clones the repository, so a generated file git ignores (bin/ once was) is missing there.
  it('every file is tracked by git, and the POSIX launcher is executable', () => {
    const git = spawnSync('git', ['ls-files', '-s', '--', CLAUDE_PLUGIN_SOURCE_DIR], { cwd: ROOT, encoding: 'utf8' });
    expect(git.status, git.stderr).toBe(0);
    const modes = new Map(
      git.stdout.trim().split('\n').map((l) => {
        const [meta, file] = l.split('\t');
        return [path.posix.relative(CLAUDE_PLUGIN_SOURCE_DIR, file!), meta!.split(' ')[0]] as const;
      }),
    );
    expect([...files.map((f) => f.path), ...Object.keys(CLAUDE_PLUGIN_STATIC_FILES)].filter((p) => !modes.has(p))).toEqual([]);
    expect(modes.get('bin/squad')).toBe('100755');
  });

  it('marketplace.json matches and points at the plugin directory', () => {
    const market = fs.readFileSync(path.join(ROOT, '.claude-plugin', 'marketplace.json'), 'utf8').replace(/\r\n/g, '\n');
    expect(market).toBe(buildClaudeMarketplace(committedVersion));
    const m = JSON.parse(market);
    expect(m.name).toBe('squad');
    expect(m.plugins).toHaveLength(1);
    expect(m.plugins[0]).toMatchObject({ name: 'squad', source: `./${CLAUDE_PLUGIN_SOURCE_DIR}`, version: committedVersion });
  });

  it.skipIf(process.platform === 'win32')('launchers are executable', () => {
    for (const f of files.filter((x) => x.executable)) {
      expect(fs.statSync(path.join(PLUGIN, f.path)).mode & 0o111, f.path).not.toBe(0);
    }
    expect(files.filter((f) => f.executable).map((f) => f.path)).toEqual(
      expect.arrayContaining(['bin/squad', 'scripts/squad.mjs']),
    );
  });
});

describe('Claude plugin: contents', () => {
  const files = new Map(build().map((f) => [f.path, f.content]));

  it('plugin.json names the plugin squad, with the metadata the validator wants', () => {
    const p = JSON.parse(files.get('.claude-plugin/plugin.json')!);
    expect(p).toMatchObject({ name: 'squad', version: committedVersion, license: 'MIT' });
    expect(p.author?.name).toBeTruthy();
    expect(p.repository).toContain('github.com/github/squad');
  });

  it('ships the coordinator, the slash commands, hooks and the squad_state MCP server', () => {
    expect(files.has('agents/squad.md')).toBe(true);
    for (const c of ['ralph', 'cast', 'ceremony', 'status', 'dashboard']) {
      expect(files.has(`commands/${c}.md`), c).toBe(true);
    }
    // The dashboard command may run exactly three invocations, chosen by the first argument word only.
    const dashboard = files.get('commands/dashboard.md')!;
    const L = '"${CLAUDE_PLUGIN_ROOT}/bin/squad" dashboard';
    expect(dashboard).toContain(`allowed-tools: Bash(${L} stop), Bash(${L} status), Bash(${L} --detach --open)\n`);
    expect(dashboard).not.toContain('$ARGUMENTS');
    expect(dashboard).toContain('`$0`');
    // Ralph takes two argument words, each matched against a fixed list; no free text reaches the prompt.
    const ralph = files.get('commands/ralph.md')!;
    expect(ralph).not.toContain('$ARGUMENTS');
    expect(ralph).toContain('`$0` and `$1`');
    for (const word of ['go', 'status', 'idle', 'issues', 'prs', 'skip-ci']) expect(ralph, word).toContain(`- \`${word}\`:`.replace('- `go`:', 'or `go`:'));
    expect(files.get('commands/cast.md')).toMatch(/<cast-request>\n\$ARGUMENTS\n<\/cast-request>/);
    expect(files.get('commands/ceremony.md')).toMatch(/<ceremony-name>\n\$ARGUMENTS\n<\/ceremony-name>/);
    // No command passes the arguments outside its fence, and only the dashboard pre-approves any tool.
    for (const [p, c] of files) {
      if (!p.startsWith('commands/')) continue;
      expect(c.replace(/<([a-z-]+)>\n\$ARGUMENTS\n<\/\1>/g, ''), p).not.toContain('$ARGUMENTS');
      if (p !== 'commands/dashboard.md') expect(c, p).not.toMatch(/^allowed-tools:/m);
    }
    // Commands go through the plugin's own launcher: a bare `squad` can be an older global CLI earlier on PATH.
    for (const [p, c] of files) {
      if (!p.startsWith('commands/')) continue;
      // The not-the-coordinator line tells the user what to run in their own terminal.
      const forBash = c.split('\n').filter((l) => !l.startsWith('If you are not the Squad coordinator'));
      expect(forBash.join('\n').match(/`squad [a-z]/g) ?? [], p).toEqual([]);
    }
    const mcp = JSON.parse(files.get('.mcp.json')!);
    expect(mcp.mcpServers.squad_state).toEqual({
      command: 'node',
      args: ['${CLAUDE_PLUGIN_ROOT}/scripts/squad.mjs', 'state-mcp'],
    });
  });

  it('the coordinator uses the plugin MCP prefix, never the project one', () => {
    const agent = files.get('agents/squad.md')!;
    expect(agent).toMatch(/^---\nname: squad\n/);
    expect(agent).toContain(`${CLAUDE_PLUGIN_MCP_PREFIX}*`);
    expect(agent).not.toContain('`mcp__squad_state__*`');
    expect(claudePluginCoordinatorInstructions()).toContain('squad init --client claude --claude-plugin');
  });

  it('hooks.json registers every Squad hook event through the launcher with --plugin', () => {
    const h = JSON.parse(files.get('hooks/hooks.json')!);
    expect(Object.keys(h.hooks).sort()).toEqual([...CLAUDE_HOOK_EVENTS].sort());
    for (const [event, groups] of Object.entries<any[]>(h.hooks)) {
      for (const g of groups) {
        for (const handler of g.hooks) {
          expect(handler.command).toBe(`node "\${CLAUDE_PLUGIN_ROOT}/scripts/squad.mjs" hook claude ${event} --plugin`);
        }
      }
    }
    expect(h.hooks.SubagentStart[0].matcher).toBe('squad|squad:squad');
  });

  it('every SKILL.md keeps its frontmatter first', () => {
    for (const [p, c] of files) {
      if (!p.endsWith('/SKILL.md')) continue;
      if (c.startsWith('---\n')) expect(c.indexOf('\n---\n'), p).toBeGreaterThan(0);
      expect(c, p).toContain('Generated by Squad from the Squad SDK');
    }
  });

  it('carries no CRLF', () => {
    for (const [p, c] of files) expect(c.includes('\r'), p).toBe(false);
  });
});

describe('Claude plugin: launcher', () => {
  const launcher = path.join(PLUGIN, 'scripts', 'squad.mjs');
  const NO_SQUAD_HOME = path.join(os.tmpdir(), 'squad-plugin-test-no-home');

  function run(env: Record<string, string>, cwd: string) {
    return spawnSync(process.execPath, [launcher, 'one', 'two words'], {
      cwd,
      // An empty Squad home: the CLI recorded on the developer's machine must not be found.
      env: { PATH: process.env.PATH ?? '', SQUAD_HOME: NO_SQUAD_HOME, ...env },
      encoding: 'utf8',
    });
  }

  it('runs SQUAD_CLI with the arguments and passes the exit code through', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'squad-plugin-'));
    try {
      const stub = path.join(dir, 'stub.js');
      fs.writeFileSync(stub, 'console.log(JSON.stringify(process.argv.slice(2))); process.exit(7);\n');
      const r = run({ SQUAD_CLI: stub }, dir);
      expect(r.status).toBe(7);
      expect(JSON.parse(r.stdout)).toEqual(['one', 'two words']);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });

  it("prefers the project's installed CLI over PATH and npx", () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'squad-plugin-'));
    try {
      const entry = path.join(dir, 'node_modules', '@bradygaster', 'squad-cli', 'dist', 'cli-entry.js');
      fs.mkdirSync(path.dirname(entry), { recursive: true });
      fs.writeFileSync(entry, 'console.log("local:" + process.argv.slice(2).join("|"));\n');
      const r = run({ CLAUDE_PROJECT_DIR: dir }, os.tmpdir());
      expect(r.status).toBe(0);
      expect(r.stdout.trim()).toBe('local:one|two words');
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });

  // Claude Code appends the plugin's bin/ after the user's PATH, so an older global CLI must not win.
  describe.skipIf(process.platform === 'win32')('skips a CLI older than the plugin', () => {
    let dir: string;
    let bin: string;
    beforeEach(() => {
      dir = fs.mkdtempSync(path.join(os.tmpdir(), 'squad-plugin-'));
      bin = path.join(dir, 'bin');
      fs.mkdirSync(bin);
      stub(path.join(bin, 'npx'), 'npx');
    });
    afterEach(() => fs.rmSync(dir, { recursive: true, force: true }));

    function stub(file: string, label: string) {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, `#!/bin/sh\necho "${label}:$*"\n`, { mode: 0o755 });
    }
    /** A global install: <prefix>/lib/node_modules/<pkg>/bin/squad, linked from bin/squad. */
    function globalCli(version: string) {
      const pkg = path.join(dir, 'lib', 'node_modules', '@bradygaster', 'squad-cli');
      stub(path.join(pkg, 'bin', 'squad'), `global@${version}`);
      fs.writeFileSync(path.join(pkg, 'package.json'), JSON.stringify({ name: '@bradygaster/squad-cli', version }));
      fs.symlinkSync(path.join(pkg, 'bin', 'squad'), path.join(bin, 'squad'));
    }
    const go = (env: Record<string, string> = {}) => run({ PATH: `${bin}:/usr/bin:/bin`, SQUAD_ALLOW_NPX: '1', ...env }, dir).stdout.trim();

    it('falls through an older squad on PATH to npx of the plugin version', () => {
      globalCli('2.0.0-preview.3');
      expect(go()).toBe(`npx:-y @bradygaster/squad-cli@${committedVersion} one two words`);
    });

    it('runs npx only when SQUAD_ALLOW_NPX is set; otherwise fails with install instructions', () => {
      globalCli('2.0.0-preview.3');
      for (const allow of [undefined, '0', '']) {
        const env: Record<string, string> = { PATH: `${bin}:/usr/bin:/bin` };
        if (allow !== undefined) env['SQUAD_ALLOW_NPX'] = allow;
        const r = run(env, dir);
        expect(r.status, String(allow)).toBe(1);
        expect(r.stdout).toBe(''); // npx never ran
        expect(r.stderr).toContain(`npm install -g @bradygaster/squad-cli@${committedVersion}`);
        expect(r.stderr).toContain('SQUAD_ALLOW_NPX=1');
      }
      for (const allow of ['1', 'true']) expect(go({ SQUAD_ALLOW_NPX: allow })).toMatch(/^npx:/);
    });

    it('uses a squad on PATH at or past the plugin version, or one whose version is unknown', () => {
      globalCli(committedVersion);
      expect(go()).toBe(`global@${committedVersion}:one two words`);
      fs.rmSync(path.join(bin, 'squad'));
      stub(path.join(bin, 'squad'), 'standalone');
      expect(go()).toBe('standalone:one two words');
    });

    it('skips an older standalone bundle (Homebrew cask) whose BUNDLE-INFO.json is outdated', () => {
      // Layout: <prefix>/Caskroom/squad/<ver>/squad-darwin-arm64/squad + BUNDLE-INFO.json.
      const bundleDir = path.join(dir, 'Caskroom', 'squad', '2.0.0-preview.3', 'squad-darwin-arm64');
      stub(path.join(bundleDir, 'squad'), `bundle@preview.3`);
      fs.writeFileSync(path.join(bundleDir, 'BUNDLE-INFO.json'), JSON.stringify({ squadVersion: '2.0.0-preview.3' }));
      fs.symlinkSync(path.join(bundleDir, 'squad'), path.join(bin, 'squad'));
      expect(go()).toBe(`npx:-y @bradygaster/squad-cli@${committedVersion} one two words`);
      // A bundle at or past the plugin version is used.
      fs.writeFileSync(path.join(bundleDir, 'BUNDLE-INFO.json'), JSON.stringify({ squadVersion: committedVersion }));
      expect(go()).toBe(`bundle@preview.3:one two words`);
    });

    it("skips an older project install, and orders prereleases by semver", () => {
      const pkg = path.join(dir, 'node_modules', '@bradygaster', 'squad-cli');
      fs.mkdirSync(path.join(pkg, 'dist'), { recursive: true });
      fs.writeFileSync(path.join(pkg, 'dist', 'cli-entry.js'), 'console.log("local")\n');
      const local = (version: string) => {
        fs.writeFileSync(path.join(pkg, 'package.json'), JSON.stringify({ name: '@bradygaster/squad-cli', version }));
        return go({ CLAUDE_PROJECT_DIR: dir });
      };
      const [core, pre = ''] = committedVersion.split('-');
      expect(local('1.1.0')).toMatch(/^npx:/);
      if (pre) {
        expect(local(`${core}-${pre.replace(/\d+$/, (n) => String(Number(n) + 1))}`)).toBe('local');
        expect(local(core!)).toBe('local'); // a release sorts after its prereleases
      }
      expect(local('99.0.0')).toBe('local');
    });
  });
});
